  var data = {
    labels: [&#039;Jul 2023&#039;, &#039;Dec 2023&#039;, &#039;Feb 2024&#039;, &#039;Apr 2024&#039;, &#039;Aug 2024&#039;, &#039;Jun 2025&#039;, &#039;Aug 2025&#039;, &#039;Dec 2025&#039;, &#039;Feb 2026&#039;],
