    new Chart(canvas, {
      type: &#039;line&#039;,
      data: {
        labels: data.labels,
        datasets: [
          {
            label: &#039;Body Fat %&#039;,
            data: data.fatPct,
            borderColor: &#039;rgb(210, 70, 70)&#039;,
